import numpy as np, mujoco
from scipy.spatial.transform import Rotation, Slerp
class Controller:
    def __init__(self,s):
        self.s=s; self.m=s.model; self.d=s.data
        self.ikd=mujoco.MjData(self.m)
        self.jids=[self.m.joint(f'robot0_joint{i}').id for i in range(1,8)]
        self.qa=np.array([self.m.jnt_qposadr[i] for i in self.jids]); self.va=np.array([self.m.jnt_dofadr[i] for i in self.jids])
        self.limits=self.m.jnt_range[self.jids]
        self.sid=self.m.site('gripper0_right_grip_site').id
        self.grip=-1
    def pos(self): return self.d.site_xpos[self.sid].copy()
    def rot(self): return self.d.site_xmat[self.sid].reshape(3,3).copy()
    def obj(self,name): return self.d.xpos[self.m.body(name+'_main').id].copy()
    def ik(self,p,R,q=None):
        d=self.ikd; m=self.m
        d.qpos[:]=self.d.qpos
        if q is not None: d.qpos[self.qa]=q
        jp=np.zeros((3,m.nv)); jr=np.zeros((3,m.nv))
        for _ in range(140):
            mujoco.mj_fwdPosition(m,d)
            ep=np.array(p)-d.site_xpos[self.sid]
            er=Rotation.from_matrix(R@d.site_xmat[self.sid].reshape(3,3).T).as_rotvec()
            if np.linalg.norm(ep)<.0001 and np.linalg.norm(er)<.001: break
            mujoco.mj_jacSite(m,d,jp,jr,self.sid)
            J=np.vstack([jp[:,self.va],jr[:,self.va]*.4]); e=np.r_[ep,er*.4]
            dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
            dq*=min(1,.14/max(np.max(np.abs(dq)),1e-9))
            d.qpos[self.qa]=np.clip(d.qpos[self.qa]+dq,self.limits[:,0]+.002,self.limits[:,1]-.002)
        return d.qpos[self.qa].copy(),np.linalg.norm(ep),np.linalg.norm(er)
    def step(self,q,grip=None):
        if grip is not None: self.grip=grip
        a=np.r_[q,self.grip,0,0,0,0,-1]
        return self.s.step(a)
    def hold(self,n=15,grip=None):
        q=self.s.targets[:7].copy()
        for _ in range(n): self.step(q,grip)
    def move(self,p,R=None,n=60,grip=None):
        p=np.array(p); p0=self.pos(); R0=self.rot()
        if R is None: R=R0
        rots=Slerp([0,1],Rotation.from_matrix([R0,R]))
        q=self.d.qpos[self.qa].copy()
        for t in np.linspace(0,1,n+1)[1:]:
            u=t*t*(3-2*t)
            q,ep,er=self.ik(p0+(p-p0)*u,rots(u).as_matrix(),q)
            self.step(q,grip)
        self.hold(10)
        print('MOVE',len(self.s.actions),'goal',p,'actual',self.pos(),'IK',ep,er,flush=True)
    def down(self,angle):
        return np.array([[np.cos(angle),np.sin(angle),0],[np.sin(angle),-np.cos(angle),0],[0,0,-1.]])
    def snap(self,path='/app/output/current.png'):
        from PIL import Image
        Image.fromarray(self.s.render_grid()).save(path)
    def status(self):
